#include <stdio.h>

static int digits(unsigned long long n, unsigned base) {
    if (n == 0) {
        return 1;
    }
    int count = 0;
    for (; n > 0; n /= base) {
        count++;
    }
    return count;
}

int main(void) {
    unsigned long long n;
    while (scanf("%llu", &n) == 1) {
        printf("%d %d\n", digits(n, 10), digits(n, 2));
    }
    return 0;
}

