#include <stdio.h>

#define MOD 1000000007LL

typedef struct {
    long long a[2][2];
} Matrix;

static Matrix multiply(Matrix x, Matrix y) {
    Matrix z;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            z.a[i][j] = (x.a[i][0] * y.a[0][j] + x.a[i][1] * y.a[1][j]) % MOD;
        }
    }
    return z;
}

static long long fibonacci(long long n) {
    Matrix result = {{{1, 0}, {0, 1}}};
    Matrix base = {{{1, 1}, {1, 0}}};
    while (n > 0) {
        if (n % 2 == 1) {
            result = multiply(result, base);
        }
        base = multiply(base, base);
        n /= 2;
    }
    return result.a[0][1];
}

int main(void) {
    long long n;
    while (scanf("%lld", &n) == 1) {
        printf("%lld\n", fibonacci(n));
    }
    return 0;
}

